"use client";

import "./collapsible.css";
import { Collapsible as BaseCollapsible } from "@base-ui/react/collapsible";
import type React from "react";
import { cn } from "tailwind-variants";

import { CollapsibleContext, useCollapsibleContext } from "./collapsible.context";
import { collapsibleVariants, type CollapsibleVariants } from "./collapsible.variants";

export type CollapsibleProps = CollapsibleVariants &
  React.ComponentProps<typeof BaseCollapsible.Root>;

export const CollapsibleRoot = ({ children, className, variant, ...props }: CollapsibleProps) => {
  const slots = collapsibleVariants({ variant });

  return (
    <CollapsibleContext.Provider value={{ slots }}>
      <BaseCollapsible.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseCollapsible.Root>
    </CollapsibleContext.Provider>
  );
};

export type CollapsibleTriggerProps = React.ComponentProps<typeof BaseCollapsible.Trigger> & {
  hideChevron?: boolean;
};

export const CollapsibleTrigger = ({
  children,
  className,
  hideChevron = false,
  ...props
}: CollapsibleTriggerProps) => {
  const { slots } = useCollapsibleContext();
  return (
    <BaseCollapsible.Trigger className={cn(slots.trigger(), className)} {...props}>
      {children}
      {!hideChevron && (
        <svg
          className="text-muted-foreground h-4 w-4 shrink-0 transition-transform duration-150 group-data-panel-open:rotate-90"
          fill="none"
          stroke="currentColor"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth="2"
          viewBox="0 0 24 24"
        >
          <path d="m9 18 6-6-6-6" />
        </svg>
      )}
    </BaseCollapsible.Trigger>
  );
};

export type CollapsiblePanelProps = React.ComponentProps<typeof BaseCollapsible.Panel>;

export const CollapsiblePanel = ({ children, className, ...props }: CollapsiblePanelProps) => {
  const { slots } = useCollapsibleContext();
  return (
    <BaseCollapsible.Panel className={cn(slots.panel(), className)} {...props}>
      <div className="text-muted-foreground px-1 py-2">{children}</div>
    </BaseCollapsible.Panel>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const collapsibleVariants = tv({
  slots: {
    root: "collapsible",
    trigger: "collapsible__trigger group",
    panel: "collapsible__panel",
  },
  variants: {
    variant: {
      default: {
        root: "collapsible--default",
      },
      outline: {
        root: "collapsible--outline",
      },
      ghost: {
        root: "collapsible--ghost",
      },
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

export type CollapsibleVariants = VariantProps<typeof collapsibleVariants>;

"use client";

import { createContext, useContext } from "react";

import { collapsibleVariants } from "./collapsible.variants";

export type CollapsibleContext = {
  slots: ReturnType<typeof collapsibleVariants>;
};

export const CollapsibleContext = createContext<CollapsibleContext | null>(null);

export const useCollapsibleContext = () => {
  const context = useContext(CollapsibleContext);
  return context ?? { slots: collapsibleVariants() };
};

.collapsible {
  @apply text-foreground flex w-full flex-col;
}

.collapsible__trigger {
  @apply border-input bg-background text-foreground hover:bg-accent hover:text-accent-foreground focus-visible:outline-ring flex h-9 items-center justify-between gap-2 rounded-md border px-3 py-2 text-sm font-medium transition-colors focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50;
}

.collapsible__panel {
  @apply flex h-[var(--collapsible-panel-height)] flex-col justify-end overflow-hidden text-sm transition-[height] duration-150 ease-out data-ending-style:h-0 data-starting-style:h-0;
}

import { CollapsiblePanel, CollapsibleRoot, CollapsibleTrigger } from "./collapsible";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/collapsible/content.md
 */
export const Collapsible = {
  Panel: CollapsiblePanel,
  Root: CollapsibleRoot,
  Trigger: CollapsibleTrigger,
};

export { CollapsiblePanel, CollapsibleRoot, CollapsibleTrigger };

export type {
  CollapsiblePanelProps,
  CollapsibleProps,
  CollapsibleTriggerProps,
} from "./collapsible";
export { CollapsibleContext, useCollapsibleContext } from "./collapsible.context";
export { type CollapsibleVariants, collapsibleVariants } from "./collapsible.variants";
